129	    /// <inheritdoc />
130	    public PostgresSqlCommandInfo BuildDropTableCommand(string schema, string tableName)
131	    {
132	        return new PostgresSqlCommandInfo(
133	            commandText: $@"DROP TABLE IF EXISTS {schema}.""{tableName}"""
134	        );
135	    }
