25	[System.Diagnostics.CodeAnalysis.SuppressMessage("Security", "CA2100:Review SQL queries for security vulnerabilities", Justification = "We need to build the full table name using schema and collection, it does not support parameterized passing.")]
26	internal class PostgresVectorStoreDbClient(NpgsqlDataSource dataSource, string schema = PostgresConstants.DefaultSchema) : IPostgresVectorStoreDbClient
27	{
28	    private readonly string _schema = schema;
29	
30	    private readonly NpgsqlConnectionStringBuilder _connectionStringBuilder = new(dataSource.ConnectionString);
31	
32	    private IPostgresVectorStoreCollectionSqlBuilder _sqlBuilder = new PostgresVectorStoreCollectionSqlBuilder();
33	
34	    public NpgsqlDataSource DataSource { get; } = dataSource;
35	
36	    public string? DatabaseName => this._connectionStringBuilder.Database;
37	
38	    /// <inheritdoc />
39	    public async Task<bool> DoesTableExistsAsync(string tableName, CancellationToken cancellationToken = default)
40	    {
41	        NpgsqlConnection connection = await this.DataSource.OpenConnectionAsync(cancellationToken).ConfigureAwait(false);
42	
43	        await using (connection)
44	        {
45	            var commandInfo = this._sqlBuilder.BuildDoesTableExistCommand(this._schema, tableName);
46	            using NpgsqlCommand cmd = commandInfo.ToNpgsqlCommand(connection);
47	            using NpgsqlDataReader dataReader = await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
48	            if (await dataReader.ReadAsync(cancellationToken).ConfigureAwait(false))
49	            {
50	                return dataReader.GetString(dataReader.GetOrdinal("table_name")) == tableName;
51	            }
52	
53	            return false;
54	        }
55	    }
56	
57	    /// <inheritdoc />
58	    public async IAsyncEnumerable<string> GetTablesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
59	    {
60	        NpgsqlConnection connection = await this.DataSource.OpenConnectionAsync(cancellationToken).ConfigureAwait(false);
61	
62	        await using (connection)
63	        {
64	            var commandInfo = this._sqlBuilder.BuildGetTablesCommand(this._schema);
65	            using NpgsqlCommand cmd = commandInfo.ToNpgsqlCommand(connection);
66	            using NpgsqlDataReader dataReader = await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
67	            while (await dataReader.ReadAsync(cancellationToken).ConfigureAwait(false))
68	            {
69	                yield return dataReader.GetString(dataReader.GetOrdinal("table_name"));
70	            }
71	        }
72	    }
